import type { Metadata } from "next";
import type { ReviewSummary } from "@/lib/reviews";
import type { BreadcrumbItem, Product } from "@/types";
import { siteConfig } from "./site-config";

const OPEN_GRAPH_LOCALE = "en_IN";
const SCHEMA_CONTEXT = "https://schema.org";

/** The image generated by app/opengraph-image.tsx. */
const DEFAULT_SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name}: ${siteConfig.tagline}`,
};

export type JsonLdData = Record<string, unknown>;

interface PageMetadataOptions {
  title: string;
  description: string;
  /** The page's path, e.g. "/category/power-banks". Used for the canonical URL. */
  path: string;
  /** Use the title exactly as given instead of appending the site name. */
  absoluteTitle?: boolean;
  /** A page-specific sharing image. Pages without one use the site-wide Open Graph image. */
  image?: { url: string; alt: string };
  /** Keep the page out of search results while still letting crawlers follow its links. */
  noIndex?: boolean;
}

/** Turns a path into a full URL on the live site. */
export function absoluteUrl(path: string): string {
  return new URL(path, siteConfig.url).toString();
}

/** Builds the title, description, canonical URL and social sharing tags for a page. */
export function buildPageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
  image,
  noIndex = false,
}: PageMetadataOptions): Metadata {
  const socialTitle = absoluteTitle ? title : `${title} | ${siteConfig.name}`;
  const images = [image ?? DEFAULT_SHARE_IMAGE];

  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      locale: OPEN_GRAPH_LOCALE,
      url: path,
      title: socialTitle,
      description,
      images,
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images,
    },
    robots: noIndex ? { index: false, follow: true } : undefined,
  };
}

export function organizationJsonLd(): JsonLdData {
  return {
    "@context": SCHEMA_CONTEXT,
    "@type": "Organization",
    name: siteConfig.name,
    url: absoluteUrl("/"),
    logo: absoluteUrl("/icon.svg"),
    description: siteConfig.description,
  };
}

/** Tells search engines the site's name, which they show above results. */
export function websiteJsonLd(): JsonLdData {
  return {
    "@context": SCHEMA_CONTEXT,
    "@type": "WebSite",
    name: siteConfig.name,
    url: absoluteUrl("/"),
  };
}

/**
 * Structured data for a breadcrumb trail.
 * `currentPath` is the page the trail ends on, used for the last item, which has no link.
 */
export function breadcrumbJsonLd(items: BreadcrumbItem[], currentPath: string): JsonLdData {
  return {
    "@context": SCHEMA_CONTEXT,
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.label,
      item: absoluteUrl(item.href ?? currentPath),
    })),
  };
}

interface ProductJsonLdOptions {
  product: Product;
  /** The product's own customer reviews. Meesho's are left out: they were not given here. */
  reviews: ReviewSummary;
  categoryName?: string;
}

/**
 * Rich-result data for a product: price, availability, pictures and, once this shop's own
 * customers have reviewed it, the rating and the latest reviews.
 */
export function productJsonLd({
  product,
  reviews,
  categoryName,
}: ProductJsonLdOptions): JsonLdData {
  const images = [product.imageUrl, ...product.extraImageUrls]
    .filter((url): url is string => Boolean(url))
    .map((url) => (url.startsWith("http") ? url : absoluteUrl(url)));
  const description = product.description.trim() || product.shortDescription.trim();
  return {
    "@context": SCHEMA_CONTEXT,
    "@type": "Product",
    name: product.title,
    description,
    image: images,
    url: absoluteUrl(`/product/${product.slug}`),
    ...(product.brand && { brand: { "@type": "Brand", name: product.brand } }),
    ...(categoryName && { category: categoryName }),
    offers: {
      "@type": "Offer",
      url: absoluteUrl(`/product/${product.slug}`),
      price: product.price,
      priceCurrency: siteConfig.currency,
      availability: `${SCHEMA_CONTEXT}/${product.inStock ? "InStock" : "OutOfStock"}`,
      itemCondition: `${SCHEMA_CONTEXT}/NewCondition`,
      seller: { "@type": "Organization", name: siteConfig.name },
    },
    ...(reviews.count > 0 && {
      aggregateRating: {
        "@type": "AggregateRating",
        ratingValue: reviews.average,
        reviewCount: reviews.count,
        bestRating: 5,
        worstRating: 1,
      },
      review: reviews.latest.slice(0, 5).map((review) => ({
        "@type": "Review",
        author: { "@type": "Person", name: review.reviewerName },
        datePublished: review.createdAt.slice(0, 10),
        reviewBody: review.comment,
        reviewRating: { "@type": "Rating", ratingValue: review.rating, bestRating: 5 },
      })),
    }),
  };
}

/** A listing page's products, in order, so search engines understand the page as a list. */
export function productListJsonLd(name: string, path: string, products: Product[]): JsonLdData {
  return {
    "@context": SCHEMA_CONTEXT,
    "@type": "CollectionPage",
    name,
    url: absoluteUrl(path),
    mainEntity: {
      "@type": "ItemList",
      numberOfItems: products.length,
      itemListElement: products.slice(0, 50).map((product, index) => ({
        "@type": "ListItem",
        position: index + 1,
        name: product.title,
        url: absoluteUrl(`/product/${product.slug}`),
      })),
    },
  };
}
